from collections.abc import Mapping


def select_visible_profiles(followers, visible_ids):
    if not isinstance(followers, (list, tuple)):
        raise ValueError("followers must be a list or tuple")
    if not isinstance(visible_ids, (list, tuple, set, frozenset)):
        raise ValueError("visible_ids must be a collection")
    if any(not isinstance(value, str) or not value for value in visible_ids):
        raise ValueError("invalid visible id")
    if len(set(visible_ids)) != len(visible_ids):
        raise ValueError("duplicate visible id")
    seen = set()
    result = []
    allowed = set(visible_ids)
    for follower in followers:
        if not isinstance(follower, Mapping):
            raise ValueError("invalid follower")
        identifier = follower.get("id")
        name = follower.get("display_name")
        profile = follower.get("profile")
        if not isinstance(identifier, str) or not identifier or identifier in seen:
            raise ValueError("invalid or duplicate follower id")
        if not isinstance(name, str) or not isinstance(profile, Mapping):
            raise ValueError("invalid follower fields")
        seen.add(identifier)
        if identifier in allowed:
            result.append({"id": identifier, "display_name": name, "profile": profile})
    return result
```

